Definition IBC_STACK : Z := 48 + PREV_NODE_STACK.

Definition ibc_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (ns : NS) (cd : Z) (ll : bool) (nd : Z) (j7 : list byte) (lo : Z) (X : list Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (cd, cd + 16)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' cd [C1 (b8 (Z.b2z ll)); CB 7 j7; C8 (wz nd)]
    /\ ANSR m' ns X /\ ACONST m'.

Definition ibc_stmt : Prop := forall (h pos cd : Z) (ns : NS) (fuel : nat) (ll : bool) (nd : Z) (lo : Z) (X : list Z)
    (b0 : byte) (j7 : list byte) (w0 : word)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ANSR m ns X -> is_Some (ns !! pos) ->
  insert_before_check fuel ns h pos = Some (ll, nd) ->
  rw_cells bsegs m cd [C1 b0; CB 7 j7; C8 w0] ->
  stk bsegs m lo (bv_unsigned sp) -> lo + IBC_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned sp <= cd ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  cd mod 8 = 0 -> accessible m cd 16 -> ACONST m ->
  evt bsegs (ibc_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ns cd ll nd j7 lo X m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz h) (wz pos) (wz cd) (wz 0) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_RB_INSERT_BEFORE_CHECK) fc None m (seg_rom bsegs)).
