(* [comment removed for export] *)
Lemma AFieldsC_cols_new : forall m Fa S L ns ls em n ndn,
  AFieldsC m Fa S L ns ls em -> cols_ok [n] (<[ n := ndn ]> ns).
Proof.
  intros m Fa S L ns ls em n ndn FC a nd La NI. pose proof FC as (NC & LC & EC & (T & HS & HR & HD & HCO) & _).
  destruct (Z.eq_dec a n) as [->|NE].
  - exfalso. apply NI. rewrite elem_of_cons. left; reflexivity.
  - rewrite lookup_insert_ne in La by (intros E; apply NE; symmetry; exact E).
    apply (HCO a nd La). rewrite elem_of_nil. intros F; exact F.
Qed.

End HCW3.
